/* eslint-disable react/jsx-max-depth */
import React, { useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useIntl } from 'react-intl';
import colors from 'Styles/colors';
import { addFilter } from 'store/Filters/actions';
import { DASHBOARD_FILTERS, RISK_BANDS, RISK_TAGS, CONFIRMED_FLAG_FILTERS, CLOSED_FILTERS, getRiskSeverity } from 'store/Filters/constants';
import { isFilteringBy } from 'store/Filters/selectors';
import { selectCurrentWorkspace } from 'store/Faraday/selectors';
import { redirect } from 'store/Router/actions';
import { selectRiskTagCounts, selectIsLoadingState } from 'store/Dashboard/selectors';
import { getRiskTagCounts } from 'Screens/Contextualization/Dashboard/actions/Actions';
import SpinnerComponent from 'Common/Components/SpinnerContainer';
import {
  Wrapper,
  Empty,
  MiddleContent,
  ScoreBlock,
  ScoreValue,
  ScoreNumber,
  ScoreMax,
  BarSection,
  GradientBarTrack,
  ScoreMarker,
  TicksRow,
  Tick,
  BandLegend,
  LegendItem,
  LegendDot,
  LegendLabel,
  MetricsRow,
  MetricCard,
  MetricHeader,
  MetricIconBadge,
  MetricValue,
  MetricLabel,
  CisaIcon,
  ExploitIcon,
  TrendingIcon,
  AvgRiskIcon
} from './styled';
import TitleWrapper from '../components/TitleWrapper';

const RISK_COLOR = {
  purple: '#9B59B6',
  red: '#dc4a4a',
  orange: '#f1ae62',
  green: '#88cc3f'
};

const BAR_BANDS = [
  { key: 'low', min: RISK_BANDS.info.min, max: RISK_BANDS.medium.min, colorKey: 'green' },
  { key: 'medium', min: RISK_BANDS.medium.min, max: RISK_BANDS.high.min, colorKey: 'orange' },
  { key: 'high', min: RISK_BANDS.high.min, max: RISK_BANDS.critical.min, colorKey: 'red' },
  { key: 'critical', min: RISK_BANDS.critical.min, max: RISK_BANDS.critical.max, colorKey: 'purple' }
];

const BAR_TICKS = [
  { value: RISK_BANDS.info.min },
  { value: RISK_BANDS.medium.min },
  { value: RISK_BANDS.high.min },
  { value: RISK_BANDS.critical.min, hideWhenNarrow: true },
  { value: RISK_BANDS.critical.max }
];

const SEVERITY_TO_COLOR_KEY = {
  info: 'green',
  low: 'green',
  medium: 'orange',
  high: 'red',
  critical: 'purple'
};

const GRADIENT_BLEND_WIDTH = 2;
const RISK_GRADIENT = (() => {
  const boundaries = [RISK_BANDS.medium.min, RISK_BANDS.high.min, RISK_BANDS.critical.min];
  const bandColors = [RISK_COLOR.green, RISK_COLOR.orange, RISK_COLOR.red, RISK_COLOR.purple];
  const stops = [`${bandColors[0]} 0%`];
  boundaries.forEach((boundary, i) => {
    stops.push(`${bandColors[i]} ${boundary - GRADIENT_BLEND_WIDTH}%`);
    stops.push(`${bandColors[i + 1]} ${boundary + GRADIENT_BLEND_WIDTH}%`);
  });
  stops.push(`${bandColors[bandColors.length - 1]} 100%`);
  return `linear-gradient(90deg, ${stops.join(', ')})`;
})();

const WorkspaceRisk = () => {
  const dispatch = useDispatch();
  const stats = useSelector(
    (state) => state.dashboard?.tools?.[3]?.data?.stats ?? {}
  );
  const isFetching = useSelector(
    (state) => state.dashboard?.loadingState?.summary ?? false
  );
  const workspaceSelected = useSelector((state) =>
    selectCurrentWorkspace(state)
  );
  const riskTagCounts = useSelector(selectRiskTagCounts);
  const isLoadingRiskTagCounts = useSelector((state) => selectIsLoadingState(state, 'riskTagCounts'));
  const { confirmed } = CONFIRMED_FLAG_FILTERS;
  const { notClosed: closed } = CLOSED_FILTERS;
  const isFilteringByConfirm = useSelector((state) => isFilteringBy(state, 'vulns', confirmed));
  const isFilteringByClosed = useSelector((state) => isFilteringBy(state, 'vulns', closed));

  const intl = useIntl();
  const translations = useMemo(
    () => ({
      title: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.title' }),
      empty: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.empty' }),
      bandCritical: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.band.critical' }),
      bandHigh: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.band.high' }),
      bandMedium: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.band.medium' }),
      bandLow: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.band.low' }),
      metricCisaKev: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.metrics.cisaKev' }),
      metricExploitAvailable: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.metrics.exploitAvailable' }),
      metricTrending: intl.formatMessage({ id: 'dashboard.widgets.workspaceRisk.metrics.trending' })
    }),
    [intl]
  );

  useEffect(() => {
    dispatch(getRiskTagCounts());
  }, [dispatch, workspaceSelected, isFilteringByConfirm, isFilteringByClosed]);

  const totalRiskAvg = stats?.total_risk_avg ?? null;
  const totalVulns = stats?.total_vulns ?? 0;

  const goToManageFilteredByTag = (filter) => {
    dispatch(addFilter('vulns', filter));
    if (isFilteringByConfirm) dispatch(addFilter('vulns', confirmed));
    if (isFilteringByClosed) dispatch(addFilter('vulns', closed));
    dispatch(redirect(`/manage/${workspaceSelected}`));
  };

  const handleCisaKevClick = () => goToManageFilteredByTag(DASHBOARD_FILTERS.vulnsByTag(RISK_TAGS.cisaKev));
  const handleExploitAvailableClick = () => goToManageFilteredByTag(DASHBOARD_FILTERS.vulnsByTag(RISK_TAGS.exploitAvailable));
  const handleTrendingClick = () => goToManageFilteredByTag(DASHBOARD_FILTERS.vulnsByTag(RISK_TAGS.trending));

  const handleCardKeyDown = (handler) => (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      handler();
    }
  };

  if (isFetching) return <SpinnerComponent height="280px" />;

  if (totalRiskAvg === null || totalVulns === 0) {
    return (
      <Wrapper>
        <TitleWrapper title={ translations.title } icon={ <AvgRiskIcon /> } />
        <Empty>{translations.empty}</Empty>
      </Wrapper>
    );
  }

  const bandLabel = {
    purple: translations.bandCritical,
    red: translations.bandHigh,
    orange: translations.bandMedium,
    green: translations.bandLow
  };

  const markerPosition = Math.min(100, Math.max(0, totalRiskAvg));
  const severityColor = RISK_COLOR[SEVERITY_TO_COLOR_KEY[getRiskSeverity(totalRiskAvg)]];

  return (
    <Wrapper>
      <TitleWrapper title={ translations.title } icon={ <AvgRiskIcon /> } />

      <MiddleContent>
        <ScoreBlock>
          <ScoreValue>
            <ScoreNumber $color={ severityColor }>{totalRiskAvg.toFixed(1)}</ScoreNumber>
            <ScoreMax>/ 100</ScoreMax>
          </ScoreValue>
        </ScoreBlock>

        <BarSection>
          <GradientBarTrack $gradient={ RISK_GRADIENT }>
            <ScoreMarker $position={ markerPosition } $glowColor={ severityColor } />
          </GradientBarTrack>

          <TicksRow>
            {BAR_TICKS.map(({ value, hideWhenNarrow }) => (
              <Tick key={ value } $position={ value } $hideWhenNarrow={ hideWhenNarrow }>{value}</Tick>
            ))}
          </TicksRow>

          <BandLegend>
            {BAR_BANDS.map((band) => (
              <LegendItem key={ band.key }>
                <LegendDot $color={ RISK_COLOR[band.colorKey] } />
                <LegendLabel>{bandLabel[band.colorKey]}</LegendLabel>
              </LegendItem>
            ))}
          </BandLegend>
        </BarSection>
      </MiddleContent>

      <MetricsRow>
        <MetricCard
          $color={ colors.red6 }
          $clickable
          onClick={ handleCisaKevClick }
          onKeyDown={ handleCardKeyDown(handleCisaKevClick) }
          role="button"
          tabIndex={ 0 }
          aria-label={ translations.metricCisaKev }
        >
          <MetricHeader>
            <MetricIconBadge $color={ colors.red6 }><CisaIcon /></MetricIconBadge>
            <MetricValue>{isLoadingRiskTagCounts ? '–' : riskTagCounts.cisaKev}</MetricValue>
          </MetricHeader>
          <MetricLabel>{translations.metricCisaKev}</MetricLabel>
        </MetricCard>
        <MetricCard
          $color={ colors.orange5 }
          $clickable
          onClick={ handleExploitAvailableClick }
          onKeyDown={ handleCardKeyDown(handleExploitAvailableClick) }
          role="button"
          tabIndex={ 0 }
          aria-label={ translations.metricExploitAvailable }
        >
          <MetricHeader>
            <MetricIconBadge $color={ colors.orange5 }><ExploitIcon /></MetricIconBadge>
            <MetricValue>{isLoadingRiskTagCounts ? '–' : riskTagCounts.exploitAvailable}</MetricValue>
          </MetricHeader>
          <MetricLabel>{translations.metricExploitAvailable}</MetricLabel>
        </MetricCard>
        <MetricCard
          $color={ colors.purple7 }
          $clickable
          onClick={ handleTrendingClick }
          onKeyDown={ handleCardKeyDown(handleTrendingClick) }
          role="button"
          tabIndex={ 0 }
          aria-label={ translations.metricTrending }
        >
          <MetricHeader>
            <MetricIconBadge $color={ colors.purple7 }><TrendingIcon /></MetricIconBadge>
            <MetricValue>{isLoadingRiskTagCounts ? '–' : riskTagCounts.trending}</MetricValue>
          </MetricHeader>
          <MetricLabel>{translations.metricTrending}</MetricLabel>
        </MetricCard>
      </MetricsRow>
    </Wrapper>
  );
};

export default WorkspaceRisk;
